void createMonoFlux() {
    Mono<String> user = Mono.just("Pravudatta");
    Flux<Integer> numbers = Flux.just(1, 2, 3, 4, 5);

    user.subscribe(System.out::println);
    numbers.subscribe(System.out::println);
}

record User(String name, int age) {}

List<User> filterAdults(List<User> users) {
    return Flux.fromIterable(users)
        .filter(user -> user.age() >= 18)
        .collectList()
        .block();
}

record Product(String name, BigDecimal price) {}

List<Product> addGst(List<Product> products) {
    return Flux.fromIterable(products)
        .map(product -> new Product(
            product.name(),
            product.price()
                .multiply(new BigDecimal("1.18"))
                .setScale(2, RoundingMode.HALF_UP)
        ))
        .collectList()
        .block();
}

record User(String id, String name) {}

Mono<User> getUser() {
    return Mono.just(new User("U101", "Ravi"));
}

Flux<String> getOrders(String userId) {
    return Flux.just(userId + "-Order1", userId + "-Order2");
}

List<String> fetchUserOrders() {
    return getUser()
        .flatMapMany(user -> getOrders(user.id()))
        .collectList()
        .block();
}

record User(String name) {}
record Account(String id, String type) {}
record UserAccountResponse(String name, String accountId, String accountType) {}

Mono<UserAccountResponse> combineProfileAndAccount(
        Mono<User> userMono,
        Mono<Account> accountMono) {
    return Mono.zip(userMono, accountMono)
        .map(tuple -> new UserAccountResponse(
            tuple.getT1().name(),
            tuple.getT2().id(),
            tuple.getT2().type()
        ));
}

Mono<String> getProfile() {
    return Mono.delay(Duration.ofMillis(500))
        .thenReturn("Profile");
}

Mono<String> getOrders() {
    return Mono.delay(Duration.ofMillis(500))
        .thenReturn("Orders");
}

Mono<String> sequentialCalls() {
    return getProfile()
        .flatMap(profile -> getOrders()
            .map(orders -> profile + " | " + orders));
}

Mono<String> concurrentCalls() {
    return Mono.zip(getProfile(), getOrders())
        .map(tuple -> tuple.getT1() + " | " + tuple.getT2());
}

Mono<String> getProductWithFallback() {
    return Mono.<String>error(
            new RuntimeException("Product service unavailable"))
        .onErrorResume(error -> Mono.just("Default product"));
}

String fetchWithRetry(AtomicInteger attempts) {
    return Mono.fromCallable(() -> {
        int attempt = attempts.incrementAndGet();
        if (attempt < 3) {
            throw new RuntimeException("Temporary failure");
        }
        return "Request successful";
    })
    .retryWhen(Retry.max(2))
    .block();
}
